import {complexFootprints as f} from './complex-footprints.js?v=references37';
const path=contour=>contour.outer.map(([x,z],i)=>`${i?'L':'M'}${x},${z}`).join(' ')+' Z';
export function planProofMarkup(){const {origin,scale}=f.transform;return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" class="cluster-proof" viewBox="-110 -120 230 250" aria-label="Сверка расположения с номерной схемой"><rect x="-500" y="-500" width="1000" height="1000" fill="#d7ded3"/><image xlink:href="assets/reference/numbered-plan.jpg" x="${-origin[0]*scale}" y="${-origin[1]*scale}" width="${661*scale}" height="${464*scale}"/><path d="${path(f.podium)}" class="proof-podium" fill="#23767d" fill-opacity="0.03" stroke="#23767d" stroke-width=".6"/><path d="${path(f.arena)}" class="proof-arena" fill="none" stroke="#855b16" stroke-width=".7"/>${f.buildings.map(b=>{const contour={outer:b.shape.map(([x,z])=>[x+b.x,z+b.z])};return `<g class="proof-building ${b.id===1?'mine':''}" data-building="${b.id}" role="button" tabindex="0" aria-label="${b.id===0?'Офисный центр 0':`Корпус ${b.id}`}"><path d="${path(contour)}" fill="white" fill-opacity=".15" stroke="white" stroke-width=".8"/><circle cx="${b.x}" cy="${b.z}" r="7.5" fill="${b.id===1?'#d6ff63':'#1b2c21'}" stroke="white" stroke-width=".5"/><text x="${b.x}" y="${b.z+2.7}" text-anchor="middle" fill="${b.id===1?'#1b2c21':'white'}" font-size="7.5" font-family="Arial">${b.id}</text></g>`}).join('')}</svg><div class="proof-caption">Корпуса по исходной схеме · двор обновлён по новым рендерам</div>`}
export function createPlanProof(host,select){const layer=document.createElement('div');layer.className='cluster-proof-layer';layer.hidden=true;layer.innerHTML=planProofMarkup();host.append(layer);const svg=layer.querySelector('svg');layer.querySelectorAll('[data-building]').forEach(el=>{el.addEventListener('click',()=>select(+el.dataset.building));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(+el.dataset.building)}})});let scale=1,cx=5,cz=5,dragged=false;const pointers=new Map();let previousDistance=null;
 function apply(){svg.setAttribute('viewBox',`${cx-115/scale} ${cz-125/scale} ${230/scale} ${250/scale}`)}
 const zoom=action=>{if(action==='reset'){scale=1;cx=5;cz=5}else scale=Math.max(1,Math.min(3,scale*(action==='in'?1.2:1/1.2)));apply()};
 layer.addEventListener('click',e=>{if(dragged){e.preventDefault();e.stopPropagation()}},true);
 svg.addEventListener('pointerdown',e=>{dragged=false;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY});previousDistance=null});
 svg.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,{...old,x:e.clientX,y:e.clientY});if(pointers.size===2){const [a,b]=[...pointers.values()],distance=Math.hypot(a.x-b.x,a.y-b.y);if(previousDistance)scale=Math.max(1,Math.min(3,scale*distance/previousDistance));previousDistance=distance;dragged=true;apply()}else{const dx=e.clientX-old.x,dy=e.clientY-old.y,ratio=Math.max(230/scale/svg.clientWidth,250/scale/svg.clientHeight);if(dragged||Math.hypot(e.clientX-old.startX,e.clientY-old.startY)>6){cx-=dx*ratio;cz-=dy*ratio;dragged=true;apply()}}});
 const end=e=>{pointers.delete(e.pointerId);previousDistance=null};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);svg.addEventListener('pointerleave',end);svg.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?'in':'out')},{passive:false});
 return{layer,setVisible(value){layer.hidden=!value},zoom,dispose(){layer.remove()}}}
